import { dataComponent, dataElement } from '../app/_component'

const mobileMenu = dataComponent('mobile-menu')

if (mobileMenu) {
    const body = document.querySelector('body')

    const sidebars = document.querySelectorAll('.sidebar')
    const sidebar = dataElement('sidebar')

    const buttonHamburger = dataElement('button-hamburger')

    const overflow = 'overflow-sidebar'
    const dataSidebarActive = 'data-sidebar-active'
    const dataTrue = 'true'
    const dataFalse = 'false'

    buttonHamburger.addEventListener('click', () => {
        checkSidebar()
        buttonHamburger.classList.toggle('active')
        body.classList.toggle(overflow)
    })

    function checkSidebar() {
        if (sidebar.getAttribute(dataSidebarActive) === dataTrue) {
            sidebar.setAttribute(dataSidebarActive, dataFalse)
        } else {
            sidebar.setAttribute(dataSidebarActive, dataTrue)
        }
    }

    sidebars.forEach(function (sidebar) {
        sidebar.onclick = function (event) {
            if (event.target == sidebar) {
                sidebar.setAttribute(dataSidebarActive, dataFalse)
                buttonHamburger.classList.remove('active')
                body.classList.remove(overflow)
            }
        }
    })
}
