import { dataComponent, dataElement } from '../../app/_component'

const modal = dataComponent('modal')

if (modal) {
    const body = document.querySelector('body');
    const modals = document.querySelectorAll('.modal');
    const overflowClass = 'overflow';
    const dataModalActive = 'data-modal-active';
    const dataTrue = 'true';
    const dataFalse = 'false';

    // Открытие модального окна
    const openModalButtons = document.querySelectorAll('[data-target]');
    openModalButtons.forEach(button => {
        button.addEventListener('click', () => {
            const targetId = button.getAttribute('data-target');
            const targetModal = document.querySelector(targetId);
            if (targetModal) {
                targetModal.setAttribute(dataModalActive, dataTrue);
                body.classList.add(overflowClass);
            }
        });
    });

    // Закрытие модального окна
    modals.forEach(modal => {
        const closeModalButtons = modal.querySelectorAll('[data-element="button-modal-close"]');
        closeModalButtons.forEach(button => {
            button.addEventListener('click', () => {
                modal.setAttribute(dataModalActive, dataFalse);
                body.classList.remove(overflowClass);
            });
        });

        // Закрытие по клику на внешнюю область модального окна
        modal.addEventListener('click', event => {
            if (event.target === modal) {
                modal.setAttribute(dataModalActive, dataFalse);
                body.classList.remove(overflowClass);
            }
        });
    });
}
