import { dataComponent, dataComponentAll } from '../../app/_component'

const customSelect = dataComponent('custom-select')

if (customSelect) {
    const selects = dataComponentAll('custom-select')
    selects.forEach(function (select) {
        new Choices(select, {
            searchEnabled: false,
            itemSelectText: '',
            shouldSort: false,
        })
    })
}
