import { dataComponent, dataElement, dataComponentAll, dataElementAll } from '../../app/_component'

const accordion = dataComponent('content-swapper')

if (accordion) {
    const accordions = dataComponentAll('accordion')

    accordions.forEach((accordion) => {
        const items = dataElementAll('accordion:item')
        
        items.forEach((item) => {
            const toggle = item.querySelector(
                '[data-element="accordion:toggle"]'
            )
            const content = item.querySelector(
                '[data-element="accordion:content"]'
            )

            toggle.addEventListener('click', function () {
                const isActive = item.classList.contains('active')

                if (isActive) {
                    item.classList.remove('active')
                    content.style.maxHeight = null
                } else {
                    item.classList.add('active')
                    content.style.maxHeight = content.scrollHeight + 'px'
                }
            })
        })
    })
}
