import { dataComponent } from '../../app/_component'

const phoneMask = dataComponent('phone-mask')

if (phoneMask) {
    function mask(event) {
        const keyCode = event.keyCode;
        const pos = this.selectionStart;
      
        if (pos < 3) event.preventDefault();
      
        const mask = '+7 (___) ___-__-__';
        let i = 0;
        const def = mask.replace(/\D/g, '');
        const val = this.value.replace(/\D/g, '');
      
        if (!this.value.startsWith('+7')) {
          this.value = '+7 ' + val;
        }
      
        let newValue = mask.replace(/[_\d]/g, (a) =>
          i < val.length ? val.charAt(i++) : a
        );
      
        i = newValue.indexOf('_');
        if (i !== -1) {
          i < 5 && (i = 3);
          newValue = newValue.slice(0, i);
        }
      
        const reg = mask
          .substr(0, this.value.length)
          .replace(/_+/g, (a) => `\\d{1,${a.length}}`)
          .replace(/[+()]/g, '\\$&');
      
        const pattern = new RegExp('^' + reg + '$');
      
        if (!pattern.test(this.value) || this.value.length < 5 ||
          (keyCode > 47 && keyCode < 58)) {
          this.value = newValue;
        }
      
        if (event.type === 'blur' && this.value.length < 5) {
          this.value = '';
        }
      }
      
      const inputs = document.querySelectorAll('[data-component="phone-mask"]');
      
      Array.from(inputs).forEach(input => {
        input.addEventListener('input', mask, false);
        input.addEventListener('focus', mask, false);
        input.addEventListener('blur', mask, false);
        input.addEventListener('keydown', mask, false);
      
        input.addEventListener('paste', (event) => {
          const data = (event.clipboardData || window.clipboardData).getData('text');
      
          if (!data.startsWith('+7')) {
            this.value = '+7 ' + data;
          } else {
            this.value = data;
          }
      
          mask.call(this, event);
        }, false);
      });
      
}
