import { dataComponent, dataComponentAll } from '../app/_component'

const contentSwapper = dataComponent('content-swapper')

if (contentSwapper) {
    const contentSwappers = dataComponentAll('content-swapper')

    contentSwappers.forEach((swapper) => {
        const buttons = swapper.querySelectorAll(
            '[data-element="content-swapper:button"]'
        )
        const contentItems = swapper.querySelectorAll(
            '[data-element="content-swapper:item"]'
        )

        buttons.forEach((button) => {
            button.addEventListener('click', function () {
                const target = button.getAttribute('data-target')

                // Удаляем класс active у всех кнопок и контентных блоков в текущем swapper
                buttons.forEach((btn) => btn.classList.remove('active'))
                contentItems.forEach((item) => item.classList.remove('active'))

                // Добавляем класс active к нажатой кнопке и соответствующему контентному блоку
                button.classList.add('active')
                swapper
                    .querySelector(
                        `[data-element="content-swapper:item"][data-target="${target}"]`
                    )
                    .classList.add('active')
            })
        })
    })
}
