document.addEventListener('DOMContentLoaded', (event) => {
    gsap.registerPlugin(ScrollTrigger, ScrollToPlugin, MotionPathPlugin)

    // Карточки из второго блока и линии
    const tlDotLineSimple1 = gsap.timeline({
        scrollTrigger: {
            trigger: '.animation-info',
            start: 'top top',
        },
    })
    const tlDotLineSimple2 = gsap.timeline({
        scrollTrigger: {
            trigger: '.animation-info',
            start: 'top top',
        },
    })
    const tlDotLineSimple3 = gsap.timeline({
        scrollTrigger: {
            trigger: '.animation-info',
            start: 'top top',
        },
    })

    // Карточки из второго блока и линии
    const tlDotLineAvatar1 = gsap.timeline({
        scrollTrigger: {
            trigger: '.animation-info',
            start: 'top top',
        },
    })
    const tlDotLineAvatar2 = gsap.timeline({
        scrollTrigger: {
            trigger: '.animation-info',
            start: 'top top',
        },
    })
    const tlDotLineAvatar3 = gsap.timeline({
        scrollTrigger: {
            trigger: '.animation-info',
            start: 'top top',
        },
    })

    tlDotLineSimple1.fromTo(
        '.animation-info-item-arrow--1 rect',
        {
            scale: 0,
        },
        {
            motionPath: {
                path: '.animation-info-item-arrow--1 path', // Линия
                align: '.animation-info-item-arrow--1 path', // Выравнивание
                alignOrigin: [0.5, 0.5], // Центр выравнивания
            },
            scale: 1,
            duration: 5,
            repeat: -1, // Бесконечная анимация
            ease: 'power2.inOut',
            stagger: 1,
        }
    )
    tlDotLineSimple2.fromTo(
        '.animation-info-item-arrow--2 rect',
        {
            scale: 0,
        },
        {
            motionPath: {
                path: '.animation-info-item-arrow--2 path', // Линия
                align: '.animation-info-item-arrow--2 path', // Выравнивание
                alignOrigin: [0.5, 0.5], // Центр выравнивания
            },
            scale: 1,
            duration: 5,
            repeat: -1, // Бесконечная анимация
            ease: 'power2.inOut',
            stagger: 1.6,
        },
        '-=0.2'
    )
    tlDotLineSimple3.fromTo(
        '.animation-info-item-arrow--3 rect',
        {
            scale: 0,
        },
        {
            motionPath: {
                path: '.animation-info-item-arrow--3 path', // Линия
                align: '.animation-info-item-arrow--3 path', // Выравнивание
                alignOrigin: [0.5, 0.5], // Центр выравнивания
            },
            scale: 1,
            duration: 5,
            repeat: -1, // Бесконечная анимация
            ease: 'power2.inOut',
            stagger: 0.9,
        },
        '-=0.6'
    )

    tlDotLineAvatar1.fromTo(
        '.animation-info-item-arrow-bottom-avatar--1 .g-avatar',
        {
            scale: 0.5,
        },
        {
            motionPath: {
                path: '.animation-info-item-arrow-bottom-avatar--1 path', // Линия
                align: '.animation-info-item-arrow-bottom-avatar--1 path', // Выравнивание
                alignOrigin: [0.5, 0.5], // Центр выравнивания
            },
            scale: 1,
            duration: 7,
            repeat: -1, // Бесконечная анимация
            ease: 'back.inOut(1.7)',
            stagger: 1,
        }
    )
    tlDotLineAvatar2.fromTo(
        '.animation-info-item-arrow-bottom-avatar--2 .g-avatar',
        {
            scale: 0.5,
        },
        {
            motionPath: {
                path: '.animation-info-item-arrow-bottom-avatar--2 path', // Линия
                align: '.animation-info-item-arrow-bottom-avatar--2 path', // Выравнивание
                alignOrigin: [0.5, 0.5], // Центр выравнивания
            },
            scale: 1,
            duration: 6,
            repeat: -1, // Бесконечная анимация
            ease: 'back.inOut(1.7)',
            stagger: 2.2,
        },
        '-=0.2'
    )
    tlDotLineAvatar3.fromTo(
        '.animation-info-item-arrow-bottom-avatar--3 .g-avatar',
        {
            scale: 0.5,
        },
        {
            motionPath: {
                path: '.animation-info-item-arrow-bottom-avatar--3 path', // Линия
                align: '.animation-info-item-arrow-bottom-avatar--3 path', // Выравнивание
                alignOrigin: [0.5, 0.5], // Центр выравнивания
            },
            scale: 1,
            duration: 7,
            repeat: -1, // Бесконечная анимация
            ease: 'back.inOut(1.7)',
            stagger: 1.8,
        },
        '-=0.6'
    )

    // При скролле уменьшаем карточки
    gsap.to('.animation-info__items', {
        scrollTrigger: {
            trigger: '.animation-info__wrap',
            start: 'top top',
            scrub: true,
        },
        scale: 1.01,
    })
})
