import { dataComponent, dataElement } from '../../app/_component'

const itemsSwiper = dataComponent('items-swiper')

if (itemsSwiper) {
    const swiper = dataElement('items-swiper:swiper')
    const nextBtn = dataElement('items-swiper:next')
    const prevBtn = dataElement('items-swiper:prev')

    const swiperWrapper = document.querySelector('.swiper-wrapper')
    const itemsSwiperButtons = document.querySelector('.items-swiper-buttons')

    new Swiper(swiper, {
        slidesPerView: 3,
        grabCursor: true,
        spaceBetween: 24,
        loop: true,

        navigation: {
            nextEl: nextBtn,
            prevEl: prevBtn,
        },

        breakpoints: {
            929: {
                slidesPerView: 3,
            },
            645: {
                slidesPerView: 2.3,
            },
            600: {
                slidesPerView: 1.8,
            },
            520: {
                slidesPerView: 1.4,
            },
            200: {
                slidesPerView: 1.2,
            },
        },
    })

    function checkBlocksAndToggleClass() {
        const blocks = swiperWrapper.children.length
        if (blocks <= 3) {
            itemsSwiperButtons.classList.add('hidden')
        } else {
            itemsSwiperButtons.classList.remove('hidden')
        }
    }

    checkBlocksAndToggleClass()
}
