import { dataComponent, dataElement } from '../../app/_component'

const infoValue = dataComponent('info-value')

if (infoValue) {
    const inputAmountMoney = dataElement('amount-money')
    const icon = dataElement('icon')
    const textDefault = dataElement('default')
    const textLow = dataElement('low')
    const textRecommended = dataElement('recommended')
    const textOverpriced = dataElement('overpriced')

    textDefault.style.display = 'block'

    inputAmountMoney.addEventListener('input', function () {
        const value = parseInt(this.value)

        // Удаляем все предыдущие классы
        icon.classList.remove('coral', 'green', 'blue')
        textLow.style.display = 'none'
        textRecommended.style.display = 'none'
        textOverpriced.style.display = 'none'

        // Добавляем новый класс в зависимости от значения
        if (value <= 12000) {
            icon.classList.add('coral')
            textLow.style.display = 'block'
            textDefault.style.display = 'none'
        } else if (value <= 60000) {
            icon.classList.add('green')
            textRecommended.style.display = 'block'
            textDefault.style.display = 'none'
        } else if (value <= 90000 || value >= 90000) {
            icon.classList.add('blue')
            textOverpriced.style.display = 'block'
            textDefault.style.display = 'none'
        }

        // Если input пустой, то применяем стандартные стили
        if (this.value === '') {
            icon.classList.remove('coral', 'green', 'blue')
            textLow.style.display = 'none'
            textRecommended.style.display = 'none'
            textOverpriced.style.display = 'none'
            textDefault.style.display = 'block'
        }
    })
}
